package net.hivel.islandsrpg.level;
import net.hivel.islandsrpg.IslandsRPGPlugin; import net.hivel.islandsrpg.data.PlayerData; import net.hivel.islandsrpg.util.*; import org.bukkit.Sound; import org.bukkit.entity.Player;
public class LevelService { private final IslandsRPGPlugin plugin; private XpFormula formula; public LevelService(IslandsRPGPlugin plugin){this.plugin=plugin; this.formula=new XpFormula(plugin.getConfig());} public void reload(){formula=new XpFormula(plugin.getConfig());} public long requiredXp(int level){return formula.requiredXp(level);} public int maxLevel(){return formula.maxLevel();} public void addXp(Player p,long amount){PlayerData d=plugin.data().get(p); d.xp+=Math.max(0,amount); boolean up=false; while(d.level<maxLevel() && d.xp>=requiredXp(d.level)){d.xp-=requiredXp(d.level); d.level++; d.statPoints+=plugin.getConfig().getInt("leveling.stat-points-per-level",3); up=true; plugin.quests().handleReachLevel(p,d.level);} if(d.level>=maxLevel()) d.xp=Math.min(d.xp, requiredXp(d.level)); if(up){String msg=plugin.message("level-up").replace("%level%", String.valueOf(d.level)); p.sendMessage(ColorUtil.color(msg)); if(plugin.getConfig().getBoolean("leveling.sound.enabled",true)){try{p.playSound(p.getLocation(), Sound.valueOf(plugin.getConfig().getString("leveling.sound.name","ENTITY_PLAYER_LEVELUP")),1,1);}catch(Exception ignored){}} if(plugin.getConfig().getBoolean("leveling.title.enabled",true)) p.sendTitle(ColorUtil.color(plugin.getConfig().getString("leveling.title.title","&6ʟᴇᴠᴇʟ ᴜᴘ")), ColorUtil.color(plugin.getConfig().getString("leveling.title.subtitle","").replace("%level%",String.valueOf(d.level))),10,40,10); plugin.data().save(d);} } public void setLevel(Player p,int level){PlayerData d=plugin.data().get(p); d.level=(int)NumberUtil.clamp(level,1,maxLevel()); d.xp=0; plugin.quests().handleReachLevel(p,d.level); plugin.data().save(d);} }
